changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS nexus_test.p35b_retry_gate_seq;

CREATE TABLE IF NOT EXISTS nexus_test.p35b_retry_gate_cfg (
    target    text   NOT NULL,
    racer     text   NOT NULL,
    delete_on bigint NOT NULL
);

CREATE OR REPLACE FUNCTION nexus_test.p35b_retry_gate() RETURNS trigger AS $$
DECLARE
    v_racer     text;
    v_delete_on bigint;
BEGIN
    SELECT g.racer, g.delete_on INTO v_racer, v_delete_on
      FROM nexus_test.p35b_retry_gate_cfg g
     WHERE g.target = NEW.collection
     LIMIT 1;
    IF FOUND AND nextval('nexus_test.p35b_retry_gate_seq') = v_delete_on THEN
        EXECUTE format('DELETE FROM %I.%I WHERE tenant_id = $1 AND collection = $2 AND chash = $3',
                       TG_TABLE_SCHEMA, TG_TABLE_NAME)
            USING NEW.tenant_id, v_racer, NEW.chash;
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

CREATE TRIGGER p35b_retry_gate_trigger BEFORE INSERT ON nexus.chunks
FOR EACH ROW EXECUTE FUNCTION nexus_test.p35b_retry_gate();

CREATE TRIGGER p35b_retry_gate_trigger BEFORE INSERT ON nexus.chunk_orphaned_at
FOR EACH ROW EXECUTE FUNCTION nexus_test.p35b_retry_gate();
